import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.4s5LDCII.js";const f=JSON.parse('{"title":"成人糖尿病食养指南（2023年版）","description":"国家卫健委《成人糖尿病食养指南（2023年版）》可执行整理：主食定量、低 GI 选择的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人糖尿病食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","source_url":"https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml","status":"现行","tags":["糖尿病","食养","血糖","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人糖尿病食养指南（2023年版）》可执行整理：主食定量、低 GI 选择的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/diabetes-2023.md","filePath":"guides/diabetes-2023.md"}'),i={name:"guides/diabetes-2023.md"};function h(s,t,g,o,l,b){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人糖尿病食养指南-2023年版" tabindex="-1">成人糖尿病食养指南（2023年版） <a class="header-anchor" href="#成人糖尿病食养指南-2023年版" aria-label="Permalink to &quot;成人糖尿病食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人糖尿病患者及糖尿病前期人群，以及需要为患者安排日常饮食的家庭成员；基层卫生工作者与营养指导人员亦可参考（<a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>八条原则</strong>：食物多样、建立合理膳食习惯 → 能量适宜、控制超重肥胖和预防消瘦 → 主食定量、优选全谷物和低 GI 食物 → 积极运动 → 清淡饮食、限制饮酒 → 食养有道 → 规律进餐、合理加餐 → 自我管理、定期营养咨询。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=5" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>蔬菜</td><td><strong>500g</strong>，深色蔬菜占一半以上，餐餐有蔬菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蛋白质 / 碳水 / 脂肪供能比</td><td><strong>15%～20% / 45%～60% / 20%～35%</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>能量参考</td><td>60kg 轻体力活动成年女性约 <strong>1500～1800kcal</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>体重</td><td>BMI <strong>18.5～23.9</strong>（65 岁以上可适当增加）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>减重速度</td><td>每月 <strong>1～2kg</strong>，3～6 个月减 <strong>5%～10%</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>烹调油</td><td><strong>≤25g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>食盐</td><td><strong>≤5g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>运动</td><td><strong>每周至少 5 天、每次 30～45 分钟</strong>，中等强度占 50% 以上</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>抗阻运动</td><td><strong>每周 2 次</strong>（哑铃、俯卧撑、器械）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>主食优先买全谷物、各种豆类等低 GI 食材</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>常买鱼、禽，适量蛋和畜肉；奶类和大豆天天有</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>少买肥肉和烟熏、烘烤、腌制等加工肉类制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>【本站提示】包装食品看配料表里&quot;糖&quot;排位和碳水含量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=13" target="_blank" rel="noreferrer">三(八)</a></td></tr></tbody></table><h3 id="🍳-做" tabindex="-1">🍳 做 <a class="header-anchor" href="#🍳-做" aria-label="Permalink to &quot;🍳 做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>少油、少盐、少糖；控制油、盐、糖使用量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>主食定量，学习食物计量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>【本站提示】用生重称重法掌握自己的&quot;一份主食&quot;（50g 生重换算成熟重）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr></tbody></table><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么吃</th><th>出处</th></tr></thead><tbody><tr><td>餐餐有蔬菜（500g，深色过半）；水果<strong>限量</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>减少肥肉摄入，限制酱油、鸡精、味精、咸菜、咸肉、酱菜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>每日烹调油 25g 以内，食盐 5g 以内</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>足量饮用白水，可适量淡茶或咖啡，<strong>不喝含糖饮料</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>规律进餐、合理加餐，促进餐后血糖稳定</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=12" target="_blank" rel="noreferrer">三(七)</a></td></tr><tr><td>按证型选食药物质：阴虚热盛（桑叶、决明子、莲子）/ 气阴两虚（桑椹、枸杞子、葛根）/ 阴阳两虚（山药、茯苓、肉桂）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=11" target="_blank" rel="noreferrer">三(六)</a></td></tr></tbody></table><h3 id="🏃-动" tabindex="-1">🏃 动 <a class="header-anchor" href="#🏃-动" aria-label="Permalink to &quot;🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么动</th><th>出处</th></tr></thead><tbody><tr><td><strong>餐后运动</strong>，每周至少 5 天、每次 30～45 分钟，中等强度（快走、骑车、乒乓球、羽毛球、慢跑、游泳）占 50% 以上</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>如无禁忌，每周 2 次抗阻运动，提高肌肉力量和耐力</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td><strong>运动前后加强血糖监测，避免低血糖</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>合并消瘦或营养不良者：在营养指导人员指导下增加膳食能量与蛋白质，结合抗阻运动增重</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>自我管理、定期营养咨询，提高血糖控制能力</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=13" target="_blank" rel="noreferrer">三(八)</a></td></tr><tr><td>能量需求因人因血糖调节而异：咨询营养指导人员制定个性化方案</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>在医师和营养指导人员指导下开展合理膳食与适量运动，防治并发症</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>老龄患者特别注意预防肌肉衰减、保持健康体重</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;糖尿病就该饿瘦&quot;</td><td>合并消瘦或营养不良者应<strong>增加</strong>膳食能量和蛋白质、结合抗阻运动增重</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>&quot;无糖食品随便吃&quot;</td><td>主食定量是控血糖核心，碳水供能占 45%～60% 且优选低 GI</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;喝点酒降糖&quot;</td><td>饮酒扰乱正常膳食和用药、可致血糖波动，用胰岛素或促泌剂时低血糖风险增加</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>&quot;只控糖不控盐油&quot;</td><td>控制油、盐、糖三者，油 25g、盐 5g 以内</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h2 id="食谱怎么用" tabindex="-1">食谱怎么用 <a class="header-anchor" href="#食谱怎么用" aria-label="Permalink to &quot;食谱怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=14" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong>：分食物类别的选择与推荐量。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=17" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong>：同类食物等量交换，配食谱使用。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=22" target="_blank" rel="noreferrer">附录3《不同地区食谱示例》</a></strong>：东北、西北、华北、华东、华中、西南、华南七大地区，每区按季节给食谱套餐——先找地区再看季节。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=61" target="_blank" rel="noreferrer">附录4《食养方举例》</a><strong>与</strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/diabetes2023.pdf#page=64" target="_blank" rel="noreferrer">附录5《诊断标准》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',26)])])}const p=e(i,[["render",h]]);export{f as __pageData,p as default};
